int HWWall::CreateVertices(FFlatVertex *&ptr, bool split)
{
	if (lightmaptile >= 0)
	{
		LightmapTile* tile = &level.levelMesh->GetLightmapTile(lightmaptile);
		FVector2 lolft = tile->ToUV(FVector3(glseg.x1, glseg.y1, zbottom[0]), level.levelMesh->Lightmap.TextureSize);
		FVector2 uplft = tile->ToUV(FVector3(glseg.x1, glseg.y1, ztop[0]), level.levelMesh->Lightmap.TextureSize);
		FVector2 uprgt = tile->ToUV(FVector3(glseg.x2, glseg.y2, ztop[1]), level.levelMesh->Lightmap.TextureSize);
		FVector2 lorgt = tile->ToUV(FVector3(glseg.x2, glseg.y2, zbottom[1]), level.levelMesh->Lightmap.TextureSize);
		lightuv[LOLFT] = { lolft.X, lolft.Y };
		lightuv[UPLFT] = { uplft.X, uplft.Y };
		lightuv[UPRGT] = { uprgt.X, uprgt.Y };
		lightuv[LORGT] = { lorgt.X, lorgt.Y };
		lindex = (float)tile->AtlasLocation.ArrayIndex;
	}
	else
	{
		lightuv[LOLFT] = { 0.0f, 0.0f };
		lightuv[UPLFT] = { 0.0f, 0.0f };
		lightuv[UPRGT] = { 0.0f, 0.0f };
		lightuv[LORGT] = { 0.0f, 0.0f };
		lindex = -1.0f;
	}

	auto oo = ptr;
	ptr->Set(glseg.x1, zbottom[0], glseg.y1, tcs[LOLFT].u, tcs[LOLFT].v, lightuv[LOLFT].u, lightuv[LOLFT].v, lindex);
	ptr++;
	if (split && glseg.fracleft == 0) SplitLeftEdge(ptr);
	ptr->Set(glseg.x1, ztop[0], glseg.y1, tcs[UPLFT].u, tcs[UPLFT].v, lightuv[UPLFT].u, lightuv[UPLFT].v, lindex);
	ptr++;
	if (split && !(flags & HWF_NOSPLITUPPER && seg->sidedef->numsegs > 1)) SplitUpperEdge(ptr);
	ptr->Set(glseg.x2, ztop[1], glseg.y2, tcs[UPRGT].u, tcs[UPRGT].v, lightuv[UPRGT].u, lightuv[UPRGT].v, lindex);
	ptr++;
	if (split && glseg.fracright == 1) SplitRightEdge(ptr);
	ptr->Set(glseg.x2, zbottom[1], glseg.y2, tcs[LORGT].u, tcs[LORGT].v, lightuv[LORGT].u, lightuv[LORGT].v, lindex);
	ptr++;
	if (split && !(flags & HWF_NOSPLITLOWER) && seg->sidedef->numsegs > 1) SplitLowerEdge(ptr);
	return int(ptr - oo);
}
